function fillProductLabelFields(id){const form=$('#productEditForm');if(!form)return;const p=productRegistry.find(x=>x.id===id),card=technicalCard(id),m=card.labelMeta||{},n=m.nutrition||{},bakery=(typeof bakerySettings!=='undefined'?bakerySettings:read('panora-bakery-settings',{}));const set=(name,val)=>{if(form.elements[name])form.elements[name].value=val??''};set('labelLegalRu',m.legalNames?.ru||p?.names?.ru||'');set('labelLegalEn',m.legalNames?.en||p?.names?.en||'');set('labelLegalEs',m.legalNames?.es||p?.names?.es||'');set('labelGtin',m.gtin||'');set('labelSku',m.sku||card.sku||'');set('labelNetWeight',m.netWeightG||'');set('labelShelfLife',card.shelfLifeDays||m.shelfLifeDays||'');set('labelQrUrl',m.qrUrl||'');set('labelClaims',m.claims||'');set('labelManufacturer',card.manufacturer||bakery.legalName||'Panora');set('labelCountry',card.country||'España');set('labelStorageRu',card.storageRu||'');set('labelStorageEn',card.storageEn||'');set('labelStorageEs',card.storageEs||'');[['nutKj','kj'],['nutKcal','kcal'],['nutFat','fat'],['nutSat','saturates'],['nutCarbs','carbs'],['nutSugars','sugars'],['nutProtein','protein'],['nutSalt','salt']].forEach(([field,key])=>set(field,n[key]??''));const status=$('#productLabelSafetyStatus'),comp=composition(id,'ru'),alls=productAllergens(id);if(status)status.innerHTML=`<strong>${comp?'Состав заполнен':'⚠ Состав не заполнен'}</strong><span>${alls.length?`Аллергены: ${alls.map(x=>allergenName(x,'ru')).join(', ')}`:'Аллергены не отмечены'}</span>`}
function captureProductLabelFields(form){const f=new FormData(form);return{legalNames:{ru:String(f.get('labelLegalRu')||'').trim(),en:String(f.get('labelLegalEn')||'').trim(),es:String(f.get('labelLegalEs')||'').trim()},gtin:String(f.get('labelGtin')||'').replace(/\s/g,''),sku:String(f.get('labelSku')||'').trim(),netWeightG:Math.max(0,num(f.get('labelNetWeight')))||0,shelfLifeDays:Math.max(0,Math.floor(num(f.get('labelShelfLife')))),qrUrl:String(f.get('labelQrUrl')||'').trim(),claims:String(f.get('labelClaims')||'').trim(),manufacturer:String(f.get('labelManufacturer')||'').trim(),country:String(f.get('labelCountry')||'').trim(),storageRu:String(f.get('labelStorageRu')||'').trim(),storageEn:String(f.get('labelStorageEn')||'').trim(),storageEs:String(f.get('labelStorageEs')||'').trim(),nutrition:{kj:Math.max(0,num(f.get('nutKj'))),kcal:Math.max(0,num(f.get('nutKcal'))),fat:Math.max(0,num(f.get('nutFat'))),saturates:Math.max(0,num(f.get('nutSat'))),carbs:Math.max(0,num(f.get('nutCarbs'))),sugars:Math.max(0,num(f.get('nutSugars'))),protein:Math.max(0,num(f.get('nutProtein'))),salt:Math.max(0,num(f.get('nutSalt')))}}}
