async function labelHtml(p,row,{preview=false}={}){const lang=builder.language,c=C(lang),card=technicalCard(p.id),m=card.labelMeta||{},profile=labelProfile(),name=productLabel(p.id,lang),legal=m.legalNames?.[lang]||name,weight=Math.max(0,num(m.netWeightG||p.weight)),price=Math.max(0,num(p.basePrice)),perKg=weight?price/(weight/1000):0,comp=composition(p.id,lang),contains=productAllergens(p.id),may=Array.isArray(card.mayContain)?card.mayContain:[],bake=builder.bakeDate,lot=row.lot||latestLot(p.id,bake),best=row.bestBefore||addDays(bake,card.shelfLifeDays),storage=lang==='en'?(card.storageEn||card.storageRu||''):lang==='es'?(card.storageEs||card.storageRu||''):(card.storageRu||''),manufacturer=card.manufacturer||(typeof bakerySettings!=='undefined'?bakerySettings.legalName:'Panora')||'Panora',address=(typeof bakerySettings!=='undefined'?(bakerySettings.address||bakerySettings.billingAddress):'')||'',country=card.country||'',barcode=builder.showBarcode?eanSvg(m.gtin):'',target=builder.showQr?qrTarget(builder.qrMode,p.id,profile):'',qr=target?await qrData(target):'',claims=String(m.claims||'').trim(),n=m.nutrition||{};const dims=builderDimensions(),sizeClass=`pl-size-${dims.w}x${dims.h}`;const brand=builder.showBrand?`<div class="pl-brand"><span class="pl-brand-mark">P</span><div class="pl-brand-text"><strong>${esc(profile.brandName||'Panora')}</strong>${profile.tagline?`<small>${esc(profile.tagline)}</small>`:''}</div></div>`:'';const priceBlock=builder.showPrice?`<div class="pl-price"><strong>${price.toFixed(2).replace('.',',')} €</strong>${weight?`<small>${perKg.toFixed(2).replace('.',',')} ${esc(c.kg)}</small>`:''}</div>`:'';const codes=(barcode||qr)?`<div class="pl-codes">${barcode?`<div class="pl-barcode">${barcode}</div>`:''}${qr?`<div class="pl-qr"><img src="${qr}" alt="QR"><small>${esc(c.scan)}</small></div>`:''}</div>`:'';if(builder.template==='shelf')return `<article class="pl-label pl-template-shelf ${sizeClass}" style="--pl-w:${dims.w}mm;--pl-h:${dims.h}mm">${brand}<div class="pl-shelf-main"><div class="pl-shelf-copy"><h3>${esc(name)}</h3>${claims?`<p class="pl-claims">${esc(claims)}</p>`:''}<p class="pl-weight">${weight?`${weight} г`:''}</p></div>${priceBlock}</div>${codes}</article>`;const safetyLines=`<div class="pl-copy">${comp?`<p><b>${esc(c.ingredients)}:</b> ${esc(comp)}</p>`:`<p class="pl-missing">⚠ ${esc(c.ingredients)}: —</p>`}${contains.length?`<p><b>${esc(c.allergens)}:</b> <strong class="pl-allergens">${esc(contains.map(x=>allergenName(x,lang)).join(', '))}</strong></p>`:''}${may.length?`<p><b>${esc(c.may)}:</b> ${esc(may.map(x=>allergenName(x,lang)).join(', '))}</p>`:''}</div>`;const meta=`<div class="pl-meta"><span>${esc(c.net)}: <b>${weight?`${weight} g`:'—'}</b></span>${bake?`<span>${esc(c.baked)}: <b>${esc(fmtDate(bake,lang))}</b></span>`:''}${best?`<span>${esc(c.best)}: <b>${esc(fmtDate(best,lang))}</b></span>`:''}${lot?`<span>${esc(c.lot)}: <b>${esc(lot)}</b></span>`:''}</div>`;const producer=`<div class="pl-producer">${storage?`<p><b>${esc(c.storage)}:</b> ${esc(storage)}</p>`:''}<p><b>${esc(c.producer)}:</b> ${esc(manufacturer)}${address?`, ${esc(address)}`:''}</p>${country?`<p><b>${esc(c.origin)}:</b> ${esc(country)}</p>`:''}</div>`;const title=`<div class="pl-title-price"><div class="pl-title-copy"><h3>${esc(legal)}</h3>${claims?`<p class="pl-claims">${esc(claims)}</p>`:''}</div>${priceBlock}</div>`;if(builder.template==='package')return `<article class="pl-label pl-template-package ${sizeClass}" style="--pl-w:${dims.w}mm;--pl-h:${dims.h}mm">${brand}${title}${safetyLines}${meta}${producer}${codes}</article>`;const nutrition=nutritionHtml(n,c);return `<article class="pl-label pl-template-full ${sizeClass}" style="--pl-w:${dims.w}mm;--pl-h:${dims.h}mm">${brand}${title}<div class="pl-full-grid ${nutrition?'':'pl-full-no-nutrition'}"><div class="pl-full-text">${safetyLines}${meta}${producer}</div>${nutrition}</div>${codes}</article>`}
async function previewHtml(){const selected=productList().filter(p=>builder.products[p.id]?.selected),parts=[];for(const p of selected){const row=builder.products[p.id]||{};parts.push(await labelHtml(p,row,{preview:true}))}return parts.join('')||'<div class="pl-preview-empty">Выберите товар для предпросмотра.</div>'}
const nextFrame=()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
function renderedFitIssues(root=document){const issues=[];root.querySelectorAll?.('.pl-label').forEach((el,index)=>{const badW=el.scrollWidth>el.clientWidth+1,badH=el.scrollHeight>el.clientHeight+1,bad=badW||badH;el.classList.toggle('pl-fit-fail',bad);if(bad)issues.push(`Этикетка ${index+1} не помещается в ${builder.size} мм. Выберите больший размер или сократите необязательный текст.`)});return issues}
async function measureLabelFit(labels){const host=document.createElement('div');host.className='pl-fit-measure';host.innerHTML=labels.join('');document.body.appendChild(host);await nextFrame();const issues=renderedFitIssues(host);host.remove();return issues}
async function renderPreview(){const root=$('#plPreview');if(!root)return;root.dataset.loading='1';root.innerHTML='<div class="pl-preview-empty">Готовим предпросмотр…</div>';root.innerHTML=await previewHtml();delete root.dataset.loading;await nextFrame();const warn=[...warnings(),...renderedFitIssues(root)],box=$('#plWarnings');if(box)box.innerHTML=warn.length?`<strong>Проверьте перед печатью</strong><ul>${[...new Set(warn)].map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<span class="pl-ok">✓ Всё помещается · коды имеют безопасный размер для печати</span>'}
function collectRowsFromUi(){document.querySelectorAll('[data-label-product-row]').forEach(el=>{const id=el.dataset.labelProductRow,row=builder.products[id]||{};el.querySelectorAll('[data-pl-field]').forEach(input=>{const key=input.dataset.plField;row[key]=input.type==='checkbox'?input.checked:input.type==='number'?Math.max(1,Number(input.value||1)):input.value});builder.products[id]=row});saveBuilder()}
function history(){return read(HISTORY_KEY,[])}
function renderHistory(){const root=$('#plHistory');if(!root)return;const rows=history();root.innerHTML=rows.length?rows.slice(0,8).map((x,i)=>`<button type="button" class="pl-history-row" data-pl-history="${i}"><span>${esc(new Date(x.at).toLocaleString('ru-RU'))}</span><strong>${esc(x.templateLabel)} · ${x.count} шт.</strong><small>${esc((x.products||[]).map(p=>p.name).join(', '))}</small></button>`).join(''):'<p class="pl-history-empty">Истории печати пока нет.</p>';root.querySelectorAll('[data-pl-history]').forEach(b=>b.onclick=()=>loadHistory(Number(b.dataset.plHistory)))}
