async function printLabels(){collectRowsFromUi();normalizeTemplateSize();const selected=productList().filter(p=>builder.products[p.id]?.selected);if(!selected.length){alert('Выберите хотя бы один товар.');return}const labels=[];for(const p of selected){const row=builder.products[p.id]||{};for(let i=0;i<Math.max(1,Number(row.qty||1));i++)labels.push(await labelHtml(p,row))}const fitIssues=await measureLabelFit(labels);if(fitIssues.length){alert(`Печать остановлена: содержимое выходит за границы ${builder.size} мм.\n\n${fitIssues[0]}\n\nДля длинного состава используйте 100×70 мм. Panora не уменьшает обязательный текст до нечитаемого размера.`);return}const {w,h}=builderDimensions(),popup=window.open('','_blank','noopener,noreferrer');if(!popup){alert('Браузер заблокировал окно печати. Разрешите всплывающие окна для Panora.');return}const baseStyle=`*{box-sizing:border-box}html,body{margin:0;padding:0;background:#fff;color:#101713;font-family:Arial,sans-serif}.pl-label{width:${w}mm;height:${h}mm;overflow:hidden;border:.2mm solid #d7d7d7;background:#fff;padding:2mm;display:flex;flex-direction:column;gap:.75mm;font-family:Arial,sans-serif}.pl-brand{display:flex;align-items:center;gap:1.1mm;min-width:0}.pl-brand-mark{width:5mm;height:5mm;flex:0 0 5mm;border-radius:50%;display:grid;place-items:center;background:#315c42;color:#fff;font:bold 2.7mm Georgia}.pl-brand-text{min-width:0}.pl-brand strong{display:block;font:700 2.8mm/1.05 Georgia;overflow-wrap:anywhere}.pl-brand small{display:block;font-size:1.45mm;line-height:1.1}.pl-label h3{margin:0;font:700 2.9mm/1.06 Georgia;color:#17251c;overflow-wrap:anywhere}.pl-label p{margin:.25mm 0;font-size:1.65mm;line-height:1.18}.pl-shelf-main,.pl-title-price{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:1.5mm;align-items:start;min-width:0}.pl-shelf-main{flex:1;align-items:center}.pl-shelf-copy,.pl-title-copy{min-width:0}.pl-price{text-align:right;white-space:nowrap;min-width:0}.pl-price strong{display:block;font:bold 5.6mm/1 Arial}.pl-price small{font-size:1.55mm}.pl-weight,.pl-claims{font-size:1.7mm!important}.pl-allergens{font-weight:900}.pl-meta{display:flex;flex-wrap:wrap;gap:.35mm 1.2mm;font-size:1.45mm;line-height:1.15}.pl-producer{font-size:1.38mm;line-height:1.15}.pl-copy{font-size:1.58mm;line-height:1.16}.pl-copy p,.pl-producer p{margin:.18mm 0}.pl-brand,.pl-title-price,.pl-copy,.pl-meta,.pl-producer,.pl-codes,.pl-full-grid{flex-shrink:0}.pl-codes{margin-top:auto;display:flex;align-items:flex-end;justify-content:flex-start;gap:1.4mm;min-width:0}.pl-barcode{flex:0 1 36mm;max-width:36mm;min-width:0}.pl-ean{display:block;width:100%;height:auto;max-height:15mm}.pl-qr{flex:0 0 auto}.pl-qr img{width:12.5mm;height:12.5mm;display:block;object-fit:contain;image-rendering:pixelated}.pl-qr small{display:block;text-align:center;font-size:1.25mm;line-height:1.05;margin-top:.2mm}.pl-nutrition{font-size:1.45mm;line-height:1.12;border-top:.2mm solid #aaa;padding-top:.45mm;min-width:0}.pl-nutrition>strong{display:block;margin-bottom:.35mm}.pl-nutrition>div{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:.08mm .8mm}.pl-full-grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(30mm,.85fr);gap:2mm;min-height:0}.pl-full-no-nutrition{grid-template-columns:1fr}.pl-full-text{min-width:0}.pl-fit-fail{outline:.35mm solid #c24d42!important;outline-offset:-.35mm}.pl-fit-measure{position:fixed;left:-10000px;top:0;visibility:hidden;pointer-events:none;z-index:-1;width:max-content}.pl-size-58x40{padding:1.8mm;gap:.55mm}.pl-size-58x40 .pl-brand-mark{width:4.4mm;height:4.4mm;flex-basis:4.4mm;font-size:2.35mm}.pl-size-58x40 .pl-brand strong{font-size:2.45mm}.pl-size-58x40 .pl-brand small{display:none}.pl-size-58x40 h3{font-size:2.55mm;line-height:1.04}.pl-size-58x40 .pl-price strong{font-size:5mm}.pl-size-58x40 .pl-price small{font-size:1.35mm}.pl-size-58x40 .pl-claims,.pl-size-58x40 .pl-weight{font-size:1.5mm!important}.pl-size-58x40 .pl-codes{gap:1.2mm}.pl-size-58x40 .pl-barcode{flex-basis:31mm;max-width:31mm}.pl-size-58x40 .pl-ean{max-height:13.2mm}.pl-size-58x40 .pl-qr img{width:11.5mm;height:11.5mm}.pl-size-58x40 .pl-qr small{display:none}.pl-size-70x50 .pl-barcode{flex-basis:34mm;max-width:34mm}.pl-size-70x50 .pl-qr img{width:12.5mm;height:12.5mm}.pl-size-70x50 .pl-copy{font-size:1.55mm}.pl-size-70x50 .pl-producer{font-size:1.32mm}.pl-size-70x50 .pl-meta{font-size:1.4mm}.pl-size-100x50 .pl-barcode{flex-basis:38mm;max-width:38mm}.pl-size-100x50 .pl-qr img{width:12.5mm;height:12.5mm}.pl-size-100x50 .pl-copy{font-size:1.52mm}.pl-size-100x50 .pl-producer{font-size:1.3mm}.pl-size-100x50 .pl-meta{font-size:1.38mm}.pl-size-100x50 .pl-nutrition{font-size:1.34mm}.pl-size-100x70{padding:2.4mm;gap:.9mm}.pl-size-100x70 .pl-brand-mark{width:5.5mm;height:5.5mm;flex-basis:5.5mm;font-size:3mm}.pl-size-100x70 .pl-brand strong{font-size:3.2mm}.pl-size-100x70 .pl-brand small{font-size:1.6mm}.pl-size-100x70 h3{font-size:3.35mm}.pl-size-100x70 .pl-price strong{font-size:6.2mm}.pl-size-100x70 .pl-copy{font-size:1.85mm}.pl-size-100x70 .pl-producer{font-size:1.65mm}.pl-size-100x70 .pl-meta{font-size:1.7mm}.pl-size-100x70 .pl-nutrition{font-size:1.65mm}.pl-size-100x70 .pl-barcode{flex-basis:42mm;max-width:42mm}.pl-size-100x70 .pl-qr img{width:14mm;height:14mm}`;let body='';if(builder.paper==='a4'){const usableW=190,usableH=277,cols=Math.max(1,Math.floor(usableW/w)),rows=Math.max(1,Math.floor(usableH/h)),per=cols*rows,start=Math.max(1,Math.min(per,Number(builder.startCell||1))),cells=[...Array(start-1)].map(()=>'<div></div>'),all=[...cells,...labels];for(let i=0;i<all.length;i+=per)body+=`<section class="sheet" style="grid-template-columns:repeat(${cols},${w}mm);grid-auto-rows:${h}mm">${all.slice(i,i+per).join('')}</section>`;popup.document.write(`<title>Panora · Этикетки</title><style>@page{size:A4;margin:10mm}${baseStyle}.sheet{width:190mm;height:277mm;display:grid;align-content:start;justify-content:start;page-break-after:always}.sheet:last-child{page-break-after:auto}.sheet .pl-label{border:.15mm dashed #bbb}</style>${body}`)}else{body=labels.map(x=>`<section class="roll-page">${x}</section>`).join('');popup.document.write(`<title>Panora · Этикетки</title><style>@page{size:${w}mm ${h}mm;margin:0}${baseStyle}.roll-page{width:${w}mm;height:${h}mm;page-break-after:always}.roll-page:last-child{page-break-after:auto}.roll-page .pl-label{border:0}</style>${body}`)}popup.document.close();recordHistory(labels.length);setTimeout(()=>{try{popup.focus();popup.print()}catch{}},250)}
function wireBuilder(){const rerender=()=>{collectRowsFromUi();renderPreview()};$('#plTemplate')?.querySelectorAll('button').forEach(b=>b.onclick=()=>{autoDefaultsForTemplate(b.dataset.value);saveBuilder();renderLabelBuilder()});[['#plLanguage','language'],['#plSize','size'],['#plPaper','paper'],['#plQrMode','qrMode'],['#plBakeDate','bakeDate']].forEach(([sel,key])=>{const el=$(sel);if(el)el.onchange=()=>{builder[key]=el.value;if(key==='bakeDate'){productList().forEach(p=>{const row=builder.products[p.id]||{};if(!row.lot)row.lot=latestLot(p.id,builder.bakeDate);if(!row.bestBefore)row.bestBefore=addDays(builder.bakeDate,technicalCard(p.id).shelfLifeDays);builder.products[p.id]=row})}saveBuilder();renderLabelBuilder()}});[['#plShowBrand','showBrand'],['#plShowPrice','showPrice'],['#plShowBarcode','showBarcode'],['#plShowQr','showQr']].forEach(([sel,key])=>{const el=$(sel);if(el)el.onchange=()=>{builder[key]=el.checked;saveBuilder();renderPreview()}});const cell=$('#plStartCell');if(cell)cell.onchange=()=>{builder.startCell=Math.max(1,Number(cell.value||1));saveBuilder()};document.querySelectorAll('[data-label-product-row] input').forEach(i=>i.onchange=rerender);$('#plPrint')?.addEventListener('click',printLabels);$('#plRepeat')?.addEventListener('click',repeatLast);$('#plSaveProfile')?.addEventListener('click',()=>{const profile={brandName:$('#plBrandName')?.value.trim()||'Panora',tagline:$('#plTagline')?.value.trim()||'',website:$('#plWebsite')?.value.trim()||'',instagram:$('#plInstagram')?.value.trim()||'',whatsapp:$('#plWhatsapp')?.value.trim()||'',promoUrl:$('#plPromoUrl')?.value.trim()||''};write(PROFILE_KEY,profile);saveLabelMeta('__label_profile__',profile);renderPreview();alert('Бренд и рекламные ссылки сохранены.')});renderHistory()}
async function renderLabelBuilder(){const root=$('#priceLabelBuilder');if(!root)return;builder=readBuilder();normalizeTemplateSize();saveBuilder();root.innerHTML=`<div class="pl-layout">${controlsHtml()}<aside class="pl-preview-panel"><div class="pl-preview-head"><div><span>Предпросмотр 1:1</span><strong>${esc(builder.size)} мм</strong></div><small>Содержимое берётся из текущих карточек, рецептур и пищевой безопасности.</small></div><div class="pl-preview" id="plPreview"></div></aside></div>`;wireBuilder();await renderPreview()}
window.panoraPriceLabels={build:BUILD,normalizeEan,eanSvg,render:renderLabelBuilder,print:printLabels,warnings,measureLabelFit,minimumSizeForTemplate};
function init(){wireProductEditor();document.querySelector('[data-view="price-labels"]')?.addEventListener('click',()=>renderLabelBuilder());window.addEventListener('panora:products-changed',()=>{if($('#view-price-labels')?.classList.contains('active'))renderLabelBuilder()});window.addEventListener('panora:production-safety-changed',()=>{if($('#view-price-labels')?.classList.contains('active'))renderLabelBuilder()});if($('#view-price-labels')?.classList.contains('active'))renderLabelBuilder()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
